challenges.solution:
def parse_head(raw):
    head = raw.split("\r\n\r\n", 1)[0]
    status_line, *lines = head.split("\r\n")
    code = int(status_line.split(" ")[1])
    headers = {}
    for line in lines:
        name, _, value = line.partition(":")
        headers[name.strip().lower()] = value.strip()
    return code, headers

